PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:investmentGoal ?gName .
    FILTER(CONTAINS(LCASE(STR(?gName)), "growth"))
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:sector ?holdSector .
    FILTER(CONTAINS(LCASE(STR(?holdSector)), "technology"))
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:sector ?allocSector .
    FILTER(CONTAINS(LCASE(STR(?allocSector)), "technology"))
  }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:type ?cfType .
    FILTER(CONTAINS(LCASE(STR(?cfType)), "sip"))
  }
}
